input.command:
python3 - <<'EOF'
p='0.html'
s=open(p).read()
s=s.replace('''    * {
      margin: 0;
      padding: 0;
    }
    body {
      width: 100vw;
      height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
    }
    svg {
      width: 400px;
      height: 400px;
    }
''','''    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }
    body {
      min-height: 100vh;
      min-height: 100dvh;
      display: flex;
      justify-content: center;
      align-items: center;
    }
    svg {
      display: block;
      width: min(400px, 100vw, 100dvh);
      height: auto;
      aspect-ratio: 1;
    }
''')
s=s.replace('<svg id="ae683f770" viewBox="0 0 400 400">','<svg id="ae683f770" viewBox="0 0 400 400" role="img" aria-label="Circle">')
open(p,'w').write(s)
EOF
cat 0.html

